-- ── Macarena Sepúlveda (Chile / advanced)
UPDATE public.ai_patients SET
  enrichment_red_social = $blk${"text":"RED SOCIAL Y VÍNCULOS:\n- Tiene una hermana menor, Daniela, que vive en Valparaíso y estudia ingeniería. Hablan por teléfono cada semana.\n- Sus padres, Marta y Luis, residen en Santiago. Su madre es profesora y su padre, ingeniero retirado. Visita a sus padres al menos una vez al mes.\n- Su mejor amiga es Valentina, una colega del CESFAM, con quien suele tomar café después del trabajo para desahogarse.\n- Su colega y supervisor, el doctor Alejandro, ha notado su cambio de ánimo y le ha ofrecido apoyo profesional.\n- Mantiene contacto ocasional con un antiguo profesor de la universidad, quien siempre la inspiró en su carrera.","version":1,"generated_by":"ai","generated_at":"2026-05-08T20:43:35.084Z","model":"gpt-4o"}$blk$::jsonb,
  enrichment_lugares = $blk${"text":"LUGARES SIGNIFICATIVOS:\n- La sala de consulta en el CESFAM, con sus paredes blancas y una ventana que da a un pequeño jardín, es donde pasa la mayor parte del día.\n- Un café local cercano al CESFAM, conocido por su aroma a tostado fresco, donde se reúne con Valentina.\n- Su departamento en Santiago, decorado con tonos cálidos y plantas que dan un toque de vida, es su refugio personal.\n- Un parque cercano donde solía correr por las mañanas, ahora simplemente camina cuando puede.\n- Una librería del barrio, repleta de textos de psicología, que solía frecuentar más a menudo.","version":1,"generated_by":"ai","generated_at":"2026-05-08T20:43:35.084Z","model":"gpt-4o"}$blk$::jsonb,
  enrichment_estado_corporal = $blk${"text":"ESTADO CORPORAL Y RUTINA:\n- Sufre de insomnio desde la pérdida de su paciente, despertándose varias veces en la noche.\n- Su apetito ha disminuido; a menudo se salta el almuerzo, justificándose con la carga de trabajo.\n- Se siente agotada físicamente, pero sigue esforzándose por mantener una apariencia profesional.\n- Lleva el mismo sweater beige de cuello alto al trabajo, buscando comodidad en la rutina.\n- Su rutina matutina ha cambiado, ya no practica yoga como solía hacerlo, ahora se levanta justo a tiempo para ir al trabajo.","version":1,"generated_by":"ai","generated_at":"2026-05-08T20:43:35.084Z","model":"gpt-4o"}$blk$::jsonb,
