  SELECT 'bbbff001-3b66-4b20-8633-20efafa2d8bf'::uuid, 'frases_tipo', 1, $h${"text":"FRASES TIPO QUE DICES:\n- \"Mira loco, yo hice lo que tenía que hacer por mi hijo.\"\n- \"Diache, la vida no es fácil pero hay que seguir pa'lante.\"\n- \"Ta to, uno no puede cambiar lo que ya pasó.\"\n- \"Esa vaina del trabajo es lo que me mantiene ocupado.\"\n- \"Dime, ¿cómo hago para que mi hijo entienda?\"\n- \"No quiero más problemas, solo quiero que mi familia esté bien.\"\n- \"A veces uno se siente como si estuviera en un hoyo del que no puede salir.\"","version":1,"generated_by":"ai","generated_at":"2026-05-08T20:43:35.084Z","model":"gpt-4o"}$h$::jsonb, 'ai', NOW()
